INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "アヤネ", "2030/12/17 14:59:59", 102301, 401, 0.0, 0.0, 24001, 2, 2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "アヤネ", "2030/12/17 14:59:59", 102301, 402, 0.0, 2.21, 24002, 1, 2, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "アヤネ", "2030/12/17 14:59:59", 102301, 403, 0.0, 0.0, 24003, 2, 2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "アサヒ", "2030/12/17 14:59:59", 192201, 701, 0.0, 1.99, 24004, 2, 1, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "アサヒ", "2030/12/17 14:59:59", 192201, 702, 0.0, 2.21, 24005, 1, 2, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "アサヒ", "2030/12/17 14:59:59", 192201, 703, 0.0, 3.33, 24006, 2, 1, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "部員３", "2030/12/17 14:59:59", 192301, 801, 0.0, 0.0, 24007, 2, 2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "部員３", "2030/12/17 14:59:59", 192301, 802, 0.0, 2.68, 24008, 1, 2, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "部員３", "2030/12/17 14:59:59", 192301, 803, 0.0, 0.0, 24009, 2, 2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "", "2030/12/17 14:59:59", 192501, 501, 0.0, 0.0, 24010, 1, 1, "やった！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "", "2030/12/17 14:59:59", 192501, 502, 0.0, 0.0, 24011, 1, 1, "勝ったよ！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "", "2030/12/17 14:59:59", 192501, 503, 0.0, 0.0, 24012, 1, 1, "いい調子！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ミサト", "2030/12/17 14:59:59", 113501, 111, 0.0, 5.33, 24013, 6, 2, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ミサト", "2030/12/17 14:59:59", 113501, 112, 0.0, 6.85, 24014, 1, 2, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ミサト", "2030/12/17 14:59:59", 113501, 113, 0.0, 3.0, 24015, 1, 2, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ダイチ", "2030/12/17 14:59:59", 192401, 611, 0.0, 6.11, 24016, 1, 2, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ダイチ", "2030/12/17 14:59:59", 192401, 612, 0.0, 6.75, 24017, 1, 2, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ダイチ", "2030/12/17 14:59:59", 192401, 613, 0.0, 0.0, 24018, 2, 2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ハツネ", "2030/12/17 14:59:59", 113401, 211, 0.0, 4.52, 24019, 2, 1, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ハツネ", "2030/12/17 14:59:59", 113401, 212, 0.0, 3.89, 24020, 2, 1, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ハツネ", "2030/12/17 14:59:59", 113401, 213, 0.0, 13.49, 24021, 1, 2, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "カヤ", "2030/12/17 14:59:59", 106501, 311, 0.0, 3.17, 24022, 1, 2, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "カヤ", "2030/12/17 14:59:59", 106501, 312, 0.0, 4.42, 24023, 1, 2, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "カヤ", "2030/12/17 14:59:59", 106501, 313, 0.0, 2.89, 24024, 6, 1, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "アヤネ", "2030/12/17 14:59:59", 102301, 421, 0.0, 3.71, 24025, 4, 3, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "アサヒ", "2030/12/17 14:59:59", 192201, 721, 0.0, 5.1, 24026, 2, 1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "部員３", "2030/12/17 14:59:59", 192301, 821, 0.0, 4.34, 24027, 1, 3, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "", "2030/12/17 14:59:59", 192501, 521, 0.0, 0.0, 24028, 1, 1, "いい勝負だったよ\nまたやろうね", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ミサト", "2030/12/17 14:59:59", 113501, 101, -360.0, 5.62, 24029, 1, 2, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ミサト", "2030/12/17 14:59:59", 113501, 102, -360.0, 9.58, 24030, 1, 2, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ミサト", "2030/12/17 14:59:59", 113501, 103, -360.0, 0.0, 24031, 2, 2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ミサト", "2030/12/17 14:59:59", 113501, 104, -360.0, 9.13, 24032, 2, 1, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 24);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "2020/07/31 12:00:00", 10046, "ミサト", "2030/12/17 14:59:59", 113501, 105, -360.0, 8.27, 24033, 1, 2, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 24);
